def _get_mod():
    global _mod
    if _mod is None:
        os.environ.setdefault('TORCH_CUDA_ARCH_LIST', '9.0a')
        _mod = load_inline(
            name='h100_gemm_cuda_ext_v2',
            cpp_sources='',
            cuda_sources=_src,
            functions=None,
            extra_cuda_cflags=['-O3'],
            extra_cflags=['-O3'],
